static struct state s; /* this file is single-window: one static state */

/* Bind a registry global at a version we understand. You may never bind
 * at a higher version than the compositor offers. */
static void* bind_global(struct wl_registry* registry, uint32_t name,
                         const struct wl_interface* iface, uint32_t offered,
                         uint32_t wanted)
{
    return wl_registry_bind(registry, name, iface,
                            offered < wanted ? offered : wanted);
}

/* ---------- drawing ---------- */

/* Draw the whole window into s.pixels with cairo.
 * Layout (600x400):
 *
 *     +----------------------------------+
 *     | fox|                             |  <- input line + caret
 *     |----------------------------------|
 *     | Firefox                          |  <- suggestion rows,
 *     | Foxit Reader                     |     the selected one
 *     | ...                              |     highlighted
 *     +----------------------------------+
 */
static void render(void* pixels)
{
    /* ARGB32 on little-endian memory == WL_SHM_FORMAT_ARGB8888. */
    cairo_surface_t* target = cairo_image_surface_create_for_data(
        pixels, CAIRO_FORMAT_ARGB32, s.width, s.height, s.width * 4);
    cairo_t* cr = cairo_create(target);

    const double pad = 16.0;

    /* background */
    cairo_set_source_rgb(cr, 0.086, 0.086, 0.106);
    cairo_paint(cr);

    /* ---- the input line: typed text plus a caret behind it ---- */
    const char* query = (s.query != NULL) ? s.query : "";

    cairo_select_font_face(cr, "Sans", CAIRO_FONT_SLANT_NORMAL,
                           CAIRO_FONT_WEIGHT_NORMAL);
    cairo_set_font_size(cr, 22.0);
    cairo_set_source_rgb(cr, 0.93, 0.94, 0.97);
    cairo_move_to(cr, pad, 42.0);
    cairo_show_text(cr, query);

    cairo_text_extents_t text;
    cairo_text_extents(cr, query, &text);
    cairo_set_source_rgb(cr, 0.45, 0.60, 0.95);
    cairo_rectangle(cr, pad + text.x_advance + 2.0, 24.0, 2.0, 24.0);
    cairo_fill(cr);

    /* thin line between the input line and the list */
    cairo_set_source_rgb(cr, 0.20, 0.21, 0.27);
    cairo_rectangle(cr, pad, 62.0, s.width - 2 * pad, 1.0);
    cairo_fill(cr);

    /* ---- the suggestion rows ---- */
    const double row_h = 28.0;
    const double list_top = 74.0;
    const int max_rows = (int)((s.height - list_top - pad) / row_h);

    int rows = (s.list != NULL) ? s.list_count : 0;
    if (rows > max_rows) rows = max_rows; /* whatever fits in the window */

    cairo_set_font_size(cr, 16.0);
    for (int i = 0; i < rows; i++) {
        const double y = list_top + i * row_h;

        if (i == s.selected) {
            cairo_set_source_rgb(cr, 0.20, 0.27, 0.42);
            cairo_rectangle(cr, pad, y, s.width - 2 * pad, row_h - 4.0);
            cairo_fill(cr);
        }

        cairo_set_source_rgb(cr, i == s.selected ? 1.00 : 0.72,
                             i == s.selected ? 1.00 : 0.74,
                             i == s.selected ? 1.00 : 0.80);
        cairo_move_to(cr, pad + 10.0, y + 18.0);
        cairo_show_text(cr, s.list[i]);
    }

    cairo_destroy(cr);
    cairo_surface_destroy(target);
}

/* The compositor is done with that buffer: drawing into it is safe again.
 * `data` is the slot index we passed to wl_buffer_add_listener. */
static void handle_buffer_release(void* data, struct wl_buffer* buffer)
{
    (void)buffer;
    s.buffer_busy[(int)(intptr_t)data] = 0;
    if (s.redraw_pending) {
        s.redraw_pending = 0;
        ui_redraw();
    }
}

static const struct wl_buffer_listener buffer_listener = {
    .release = handle_buffer_release,
};

/* Create TWO 600x400 buffers. Two, not one, because a compositor only hands
 * a buffer back (wl_buffer.release) once it no longer needs it - and the
 * buffer currently on screen is exactly the one it keeps. With a single
 * buffer you would wait for a release that only comes when you commit a new
 * frame, which you cannot do because you are waiting. With two, one is
 * always free to draw into, and committing it makes the compositor release
 * the other. */
static int create_shm_buffers(void)
{
    const int stride = s.width * 4; /* ARGB8888 = 4 bytes/px */
    const int one = stride * s.height;
    const int total = one * 2;

    /* Shared memory needs a file descriptor. mkstemp + unlink gives us
     * an anonymous fd without leaving a file behind. */
    char path[] = "/tmp/pickme-shm-XXXXXX";
    int fd = mkstemp(path);
    if (fd < 0) {
        perror("mkstemp");
        return -1;
    }
    unlink(path);
    if (ftruncate(fd, total) < 0) {
        perror("ftruncate");
        close(fd);
        return -1;
    }

    s.map = mmap(NULL, total, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (s.map == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return -1;
    }

    /* Give the fd to the compositor: it becomes a "pool" of memory... */
    s.pool = wl_shm_create_pool(s.shm, fd, total);
    close(fd); /* the pool keeps its own reference to the fd */
    if (!s.pool) {
        fprintf(stderr, "wl_shm_create_pool failed\n");
        return -1;
    }

    /* ...from which we carve two rectangular "buffers". */
    for (int i = 0; i < 2; i++) {
        s.pixels[i] = (char*)s.map + (size_t)i * one;
        s.buffers[i] = wl_shm_pool_create_buffer(s.pool, i * one, s.width,
                                                 s.height, stride,
                                                 WL_SHM_FORMAT_ARGB8888);
        if (!s.buffers[i]) {
            fprintf(stderr, "wl_shm_pool_create_buffer failed\n");
            return -1;
        }
        wl_buffer_add_listener(s.buffers[i], &buffer_listener,
                               (void*)(intptr_t)i);
    }
    return 0;
}

/* ---------- what the window displays ---------- */

void ui_set_query(const char* text)
{
    s.query = text;
}

void ui_set_list(char** names, int count)
{
    s.list = names;
    s.list_count = (count > 0) ? count : 0;
    ui_set_selected(s.selected); /* keep the highlight inside the new list */
}

void ui_set_selected(int index)
{
    if (s.list_count <= 0) {
        s.selected = 0;
        return;
    }
    if (index < 0) index = 0;
    if (index >= s.list_count) index = s.list_count - 1;
    s.selected = index;
}

int ui_selected(void)
{
    return s.selected;
}

void ui_move_selection(int delta)
{
    ui_set_selected(s.selected + delta);
}

void ui_redraw(void)
{
    if (s.buffers[0] == NULL) return; /* not shown yet */

    /* Draw into a buffer the compositor is not reading. Alternate, so the
     * frame we are showing gets replaced (and therefore released). */
    int slot = -1;
    for (int k = 0; k < 2; k++) {
        const int i = (s.next_buffer + k) % 2;
        if (!s.buffer_busy[i]) {
            slot = i;
            break;
        }
    }
    if (slot < 0) {           /* both in flight: try again on the next release */
        s.redraw_pending = 1;
        return;
    }
    s.next_buffer = (slot + 1) % 2;

    render(s.pixels[slot]);

    wl_surface_attach(s.surface, s.buffers[slot], 0, 0);
    wl_surface_damage_buffer(s.surface, 0, 0, s.width, s.height);
    wl_surface_commit(s.surface);
    s.buffer_busy[slot] = 1;
}

void ui_quit(void)
{
    s.running = 0; /* run_ui()'s loop sees this and exits */
}

/* ---------- listeners (the compositor calls these) ---------- */

/* xdg_wm_base ping: the compositor checks we are alive. Always pong. */
static void handle_wm_base_ping(void* data, struct xdg_wm_base* wm_base,
                                uint32_t serial)
{
    (void)data;
    xdg_wm_base_pong(wm_base, serial);
}

static const struct xdg_wm_base_listener wm_base_listener = {
    .ping = handle_wm_base_ping,
};

/* xdg_surface configure: the compositor grants us permission to show
 * content, handed over as a serial. Content attached BEFORE this ack is
 * ignored, so the first buffer is created here. */
static void handle_xdg_surface_configure(void* data,
                                         struct xdg_surface* xdg_surface,
                                         uint32_t serial)
{
    (void)data;
    xdg_surface_ack_configure(xdg_surface, serial);
    if (s.buffers[0] == NULL) {
        if (create_shm_buffers() == 0) ui_redraw();
    }
}

static const struct xdg_surface_listener xdg_surface_listener = {
    .configure = handle_xdg_surface_configure,
};

/* The compositor suggests a size (width/height may be 0 = "you decide").
 * states is a wl_array of xdg_toplevel_state flags (maximized, focused, ...).
 * We keep our fixed 600x400 buffer for now, so we only acknowledge it.
 * NOTE: the exact signature lives in the generated header — newer xdg-shell
 * versions added the trailing `states` argument. */
static void handle_toplevel_configure(void* data, struct xdg_toplevel* toplevel,
                                      int32_t width, int32_t height,
                                      struct wl_array* states)
{
    (void)data;
    (void)toplevel;
    (void)width;
    (void)height;
    (void)states;
}

/* The user clicked the close button / Alt+F4. */
static void handle_toplevel_close(void* data, struct xdg_toplevel* toplevel)
{
    (void)data;
    (void)toplevel;
    s.running = 0; /* run_ui()'s loop sees this and exits */
}

static const struct xdg_toplevel_listener toplevel_listener = {
    .configure = handle_toplevel_configure, /* must not be NULL: libwayland
                                               aborts on NULL listener slots */
    .close = handle_toplevel_close,
};

/* Registry: the compositor announces each service once. We bind the ones
 * this app needs. Everything else (outputs, dmabuf, ...) we ignore. */
static void registry_global(void* data, struct wl_registry* registry,
                            uint32_t name, const char* interface,
                            uint32_t version)
{
    (void)data;
    if (strcmp(interface, wl_compositor_interface.name) == 0) {
        s.compositor =
            bind_global(registry, name, &wl_compositor_interface, version, 4);
    } else if (strcmp(interface, wl_shm_interface.name) == 0) {
        s.shm = bind_global(registry, name, &wl_shm_interface, version, 1);
    } else if (strcmp(interface, xdg_wm_base_interface.name) == 0) {
        s.wm_base =
            bind_global(registry, name, &xdg_wm_base_interface, version, 1);
        /* Listeners are attached HERE, right after the bind - see the note
         * on wl_seat below. */
        xdg_wm_base_add_listener(s.wm_base, &wm_base_listener, NULL);
    } else if (strcmp(interface, wl_seat_interface.name) == 0 &&
               s.seat == NULL) {
        /* v7 is plenty: we need >= 3 for wl_keyboard.release, and by v4
         * the keyboard also tells us its repeat settings. */
        s.seat = bind_global(registry, name, &wl_seat_interface, version, 7);

        /* Attach the listener IMMEDIATELY, before anything else happens.
         *
         * A compositor sends wl_seat.capabilities as soon as it creates the
         * seat, i.e. while the roundtrip right after our bind is still
         * running. libwayland does NOT queue events for a proxy that has no
         * listener yet: they are dropped on the floor and never replayed.
         * Attach the listener one roundtrip later (as connect_display used
         * to) and you never learn that a keyboard exists - no wl_keyboard is
         * ever created, so no key event ever arrives, and the window just
         * sits there ignoring your typing. */
        input_init(s.seat);
    }
}

static void registry_global_remove(void* data, struct wl_registry* registry,
                                   uint32_t name)
{
    (void)data;
    (void)registry;
    (void)name; /* a service disappeared; a full app would react here */
}

static const struct wl_registry_listener registry_listener = {
    .global = registry_global,
    .global_remove = registry_global_remove,
};

/* ---------- public API ---------- */

int connect_display(void)
{
    memset(&s, 0, sizeof s);
    s.width = 600;
    s.height = 400;

    /* NULL = the socket named by $WAYLAND_DISPLAY (usually wayland-1).
     * Passing a string here means "that socket's name", not app name. */
    s.display = wl_display_connect(NULL);
    if (s.display == NULL) {
        fprintf(stderr,
                "cannot connect to Wayland "
                "(are you inside a Wayland session?)\n");
        return -1;
    }

    s.registry = wl_display_get_registry(s.display);
    wl_registry_add_listener(s.registry, &registry_listener, NULL);
    wl_display_roundtrip(s.display); /* 1st: receive the global list */
    wl_display_roundtrip(s.display); /* 2nd: process our bind requests */

    if (s.compositor == NULL || s.shm == NULL || s.wm_base == NULL) {
        fprintf(stderr,
                "missing required global "
                "(wl_compositor / wl_shm / xdg_wm_base)\n");
        return -1;
    }
    /* xdg_wm_base's ping listener was attached at bind time (see
     * registry_global). */

    /* Build the window: surface -> xdg_surface -> xdg_toplevel. */
    s.surface = wl_compositor_create_surface(s.compositor);
    s.xdg_surface = xdg_wm_base_get_xdg_surface(s.wm_base, s.surface);
    xdg_surface_add_listener(s.xdg_surface, &xdg_surface_listener, NULL);

    s.xdg_toplevel = xdg_surface_get_toplevel(s.xdg_surface);
    xdg_toplevel_add_listener(s.xdg_toplevel, &toplevel_listener, NULL);
    xdg_toplevel_set_title(s.xdg_toplevel, "pickme");
    xdg_toplevel_set_app_id(s.xdg_toplevel, "pickme");

    /* Keyboard: input_handling.c owns the wl_keyboard. Its capabilities
     * event (the one that actually creates the keyboard object) only
     * arrives while the event loop runs, i.e. inside run_ui(). */
    /* The keyboard listener went on at bind time; this only reports a
     * compositor that offered no seat at all. */
    if (s.seat == NULL)
        fprintf(stderr, "pickme: the compositor offered no wl_seat - "
                        "you will not be able to type\n");

    /* Commit the empty surface: the compositor now sends us a configure,
     * which our listener answers by creating the buffer + first frame. */
    wl_surface_commit(s.surface);
    wl_display_roundtrip(s.display);

    if (s.buffers[0] == NULL) {
        fprintf(stderr, "no configure received from the compositor\n");
        return -1;
    }
    return 0;
}

int run_ui(void)
{
    s.running = 1;
    /* Dispatch events forever. Listeners do the work; the loop is what
     * keeps the process (and the window) alive. Returns -1 on error or
     * when the connection dies (compositor closed, session ended). */
    while (s.running && wl_display_dispatch(s.display) != -1);
    if (s.running) { /* loop ended because of an error, not window close */
        fprintf(stderr, "Wayland connection lost\n");
        return -1;
    }
    return 0;
}

void cleanup_ui(void)
{
    input_cleanup(); /* before the seat goes away */
    for (int i = 0; i < 2; i++)
        if (s.buffers[i]) wl_buffer_destroy(s.buffers[i]);
    if (s.pool) wl_shm_pool_destroy(s.pool);
    if (s.map) munmap(s.map, (size_t)s.width * s.height * 4 * 2);
    if (s.xdg_toplevel) xdg_toplevel_destroy(s.xdg_toplevel);
    if (s.xdg_surface) xdg_surface_destroy(s.xdg_surface);
    if (s.surface) wl_surface_destroy(s.surface);
    if (s.seat) wl_seat_destroy(s.seat);
    if (s.shm) wl_shm_destroy(s.shm);
    if (s.wm_base) xdg_wm_base_destroy(s.wm_base);
    if (s.compositor) wl_compositor_destroy(s.compositor);
    if (s.registry) wl_registry_destroy(s.registry);
    if (s.display) wl_display_disconnect(s.display);
    s = (struct state){0};
}
